#include "xanatoo/source_view.hpp"

#include "xanatoo/parse.hpp"

#include <stdexcept>

namespace xanatoo {

SourceViewText source_view_text(const Document& doc, SelectorKind kind,
                                std::optional<std::string_view> raw) {
  switch (kind) {
    case SelectorKind::SourceRaw:
      return {raw ? std::string(*raw)
                  : "Raw source is unavailable for this document.\n"
                    "The page was generated by an importer or service adapter.\n",
              "text"};
    case SelectorKind::SourceSexpr:
      return {serialize_sexpr(doc), "lisp"};
    case SelectorKind::SourceXml:
      return {serialize_xml(doc), "xml"};
    default:
      throw std::invalid_argument("not a source pipe");
  }
}

Document source_view_document(const SourceViewText& source) {
  Document doc;
  const NodeId root = doc.create(NodeKind::Document);
  const NodeId code = doc.create(NodeKind::CodeBlock, root);
  doc.get(code).src = source.language;
  doc.append_text(code, source.text);
  return doc;
}

}  // namespace xanatoo
